// page_store.go — page operations on the store: derived knowledge pages
// under pages/, regenerated by the evolve sweep. Page writes neither
// journal nor regenerate the index: pages are engine state outside the
// fact surfaces.

package memory

import (
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// ListPages returns the project's pages, newest UpdatedOn first with
// catalog order breaking ties. Files outside the catalog are still read
// (hand-placed files must not break the surface); staleness never
// rewrites them.
func (s *Store) ListPages() ([]Page, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.listPagesLocked()
}

func (s *Store) listPagesLocked() ([]Page, error) {
	entries, err := os.ReadDir(PagesDir(s.projectDir))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, Errorf(CodeIO, "read pages: %v", err)
	}
	var pages []Page
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), markdownExt) {
			continue
		}
		path := filepath.Join(PagesDir(s.projectDir), entry.Name())
		content, err := readMemoryFile(path)
		if err != nil {
			return nil, err
		}
		page := ParsePage(content)
		base := strings.TrimSuffix(entry.Name(), markdownExt)
		if page.Name == "" {
			page.Name = base
		}
		if page.Question == "" {
			page.Question = CollapseLine(firstNonEmptyLine(page.Body))
		}
		if info, err := os.Lstat(path); err == nil {
			page.ModTime = info.ModTime()
		}
		pages = append(pages, page)
	}
	sort.SliceStable(pages, func(i, j int) bool {
		if pages[i].UpdatedOn != pages[j].UpdatedOn {
			return pages[i].UpdatedOn > pages[j].UpdatedOn
		}
		return pageCatalogOrder(pages[i].Name) < pageCatalogOrder(pages[j].Name)
	})
	return pages, nil
}

// UpsertPage writes page, replacing the page with the same slug in place.
// The name must be a catalog slug. The body clamps at maxPageBodyBytes
// (derived state, so the composition clamp is a write bound), and an empty
// UpdatedOn stamps from the store clock.
func (s *Store) UpsertPage(page Page) (Page, error) {
	prepared, err := preparePage(page)
	if err != nil {
		return Page{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if prepared.UpdatedOn == "" {
		prepared.UpdatedOn = s.now().Format(time.DateOnly)
	}
	path := filepath.Join(PagesDir(s.projectDir), prepared.Name+markdownExt)
	if err := s.writeLocked(path, FormatPage(prepared)); err != nil {
		return Page{}, err
	}
	return prepared, nil
}

// StalePages returns the catalog slugs needing a rewrite, in rewrite order:
// missing pages first in catalog order, then existing pages whose cited
// facts dropped or changed, oldest UpdatedOn first. A page with no sources
// never goes stale, so a hand-written page survives until there is a
// provable reason to rewrite it.
func (s *Store) StalePages() ([]string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	pages, err := s.listPagesLocked()
	if err != nil {
		return nil, err
	}
	bySlug := make(map[string]*Page, len(pages))
	for i := range pages {
		bySlug[pages[i].Name] = &pages[i]
	}
	var missing, stale []string
	for _, spec := range pageCatalog {
		page, ok := bySlug[spec.Name]
		if !ok {
			missing = append(missing, spec.Name)
			continue
		}
		if s.pageStaleLocked(page) {
			stale = append(stale, spec.Name)
		}
	}
	sort.SliceStable(stale, func(i, j int) bool {
		a, b := bySlug[stale[i]], bySlug[stale[j]]
		if a.UpdatedOn != b.UpdatedOn {
			return a.UpdatedOn < b.UpdatedOn
		}
		return pageCatalogOrder(a.Name) < pageCatalogOrder(b.Name)
	})
	return append(missing, stale...), nil
}

// pageStaleLocked reports whether any cited fact dropped or changed after
// the page's last write. Callers hold the lock.
func (s *Store) pageStaleLocked(page *Page) bool {
	if len(page.Sources) == 0 {
		return false
	}
	for _, source := range page.Sources {
		fact, err := s.findFactLocked(FactSlug(source))
		if err != nil || fact == nil {
			return true
		}
		if fact.ModTime.After(page.ModTime) {
			return true
		}
	}
	return false
}
